1	// ── SQLite Database Module for Polyglot ──────────────────────────────────────
2	// Replaces JSON file storage with a local SQLite database.
3	// Uses better-sqlite3 (synchronous, fast, no async overhead).
4	// Database file: data/polyglot.db (created automatically on first access).
5	
6	const Database = require('better-sqlite3');
7	const path = require('path');
8	const fs = require('fs');
9	
10	const DB_DIR = path.join(__dirname, '..', 'data');
11	const DB_PATH = path.join(DB_DIR, 'polyglot.db');
12	const HOME = process.env.HOME || process.env.USERPROFILE || '';
13	const ORG_DIR = path.join(HOME, '.claude', 'org');
14	
15	let _db = null;
16	
17	// ── Database Lifecycle ──────────────────────────────────────────────────────
18	
19	function getDb() {
20	  if (_db) return _db;
21	  fs.mkdirSync(DB_DIR, { recursive: true });
22	  _db = new Database(DB_PATH);
23	  _db.pragma('journal_mode = WAL');
24	  _db.pragma('foreign_keys = ON');
25	  _db.pragma('busy_timeout = 5000');
26	  _db.pragma('synchronous = NORMAL');
27	  runMigrations(_db);
28	  return _db;
29	}
30	
31	function close() {
32	  if (_db) { _db.close(); _db = null; }
33	}
34	
35	// ── Prepared Statement Cache ────────────────────────────────────────────────
36	
37	const _stmts = {};
38	function stmt(sql) {
39	  if (!_stmts[sql]) _stmts[sql] = getDb().prepare(sql);
40	  return _stmts[sql];
41	}
42	
43	// ── Schema Migrations ───────────────────────────────────────────────────────
44	
45	function runMigrations(db) {
46	  db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
47	    version INTEGER PRIMARY KEY,
48	    name TEXT NOT NULL,
49	    applied_at TEXT NOT NULL DEFAULT (datetime('now'))
50	  )`);
51	
52	  const applied = new Set(db.prepare('SELECT version FROM schema_migrations').all().map(r => r.version));
53	
54	  const migrations = [
55	    { version: 1, name: 'create_all_tables', fn: createAllTables },
56	    { version: 2, name: 'import_json_data', fn: importJsonData },
57	    { version: 3, name: 'create_change_log', fn: createChangeLog },
58	  ];
59	
60	  for (const mig of migrations) {
61	    if (applied.has(mig.version)) continue;
62	    console.log(`[db] Running migration ${mig.version}: ${mig.name}`);
63	    db.transaction(() => {
64	      mig.fn(db);
65	      db.prepare('INSERT INTO schema_migrations (version, name) VALUES (?, ?)').run(mig.version, mig.name);
66	    })();
67	  }
68	}
