428	function importJsonData(db) {
429	  const ROOT = path.join(__dirname, '..');
430	
431	  function tryImport(label, fn) {
432	    try { fn(); console.log(`[db:migrate] Imported ${label}`); }
433	    catch (err) { console.warn(`[db:migrate] Skipped ${label}: ${err.message}`); }
434	  }
435	
436	  function readJsonFile(filePath) {
437	    if (!fs.existsSync(filePath)) return null;
438	    return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
439	  }
440	
441	  function readJsonlFile(filePath) {
442	    if (!fs.existsSync(filePath)) return [];
443	    return fs.readFileSync(filePath, 'utf-8').split('\n').filter(Boolean).map(line => {
444	      try { return JSON.parse(line); } catch { return null; }
445	    }).filter(Boolean);
446	  }
447	
448	  function markMigrated(filePath) {
449	    if (fs.existsSync(filePath)) {
450	      try { fs.renameSync(filePath, filePath + '.migrated'); } catch {}
451	    }
452	  }
