458	    const s = db.prepare('INSERT OR IGNORE INTO agent_runs (id,agentName,prompt,source,timestamp,duration,status,promptChars,outputChars,estimatedTokens,estimatedCost,error,metadata) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)');
459	    db.transaction(() => {
460	      for (const r of data) s.run(r.id, r.agentName, r.prompt, r.source, r.timestamp, r.duration, r.status, r.promptChars, r.outputChars, r.estimatedTokens, r.estimatedCost, r.error, JSON.stringify(r.metadata || {}));
