1128	  if (!pkCol) throw new Error(`No primary key found for table ${tableName}`);
1129	
1130	  // Snapshot old data
1131	  const oldRow = d.prepare(`SELECT * FROM "${tableName}" WHERE "${pkCol}" = ?`).get(pkValue);
1132	  if (!oldRow) throw new Error(`Row not found: ${pkCol}=${pkValue}`);
1133	
1134	  // Build UPDATE
1135	  const setClauses = [];
1136	  const values = [];
1137	  for (const [col, val] of Object.entries(updates)) {
1138	    if (col === pkCol) continue; // Don't update PK
1139	    setClauses.push(`"${col}" = ?`);
1140	    values.push(val === undefined ? null : val);
1141	  }
1142	  if (setClauses.length === 0) throw new Error('No fields to update');
1143	
1144	  values.push(pkValue);
1145	  d.prepare(`UPDATE "${tableName}" SET ${setClauses.join(', ')} WHERE "${pkCol}" = ?`).run(...values);
1146	
1147	  // Get new data
1148	  const newRow = d.prepare(`SELECT * FROM "${tableName}" WHERE "${pkCol}" = ?`).get(pkValue);
1149	
