app.put('/api/schedules/:id', rateLimit('write'), (req, res) => {
  const schedules = loadSchedules();
  const idx = schedules.findIndex(s => s.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Schedule not found' });

  const { name, agentName, prompt, cronExpr, enabled } = req.body;
  if (cronExpr && !cron.validate(cronExpr)) return res.status(400).json({ error: 'Invalid cron expression' });

  if (name !== undefined) schedules[idx].name = name;
  if (agentName !== undefined) schedules[idx].agentName = agentName;
  if (prompt !== undefined) schedules[idx].prompt = prompt;
  if (cronExpr !== undefined) schedules[idx].cron = cronExpr;
  if (enabled !== undefined) schedules[idx].enabled = enabled;
  schedules[idx].updatedAt = new Date().toISOString();
  saveSchedules(schedules);

  // Restart/stop cron job
  if (schedules[idx].enabled) startScheduleJob(schedules[idx]);
  else if (activeJobs.has(schedules[idx].id)) { activeJobs.get(schedules[idx].id).stop(); activeJobs.delete(schedules[idx].id); }

  res.json(schedules[idx]);
});

app.delete('/api/schedules/:id', rateLimit('write'), (req, res) => {
  if (activeJobs.has(req.params.id)) { activeJobs.get(req.params.id).stop(); activeJobs.delete(req.params.id); }
  saveSchedules(loadSchedules().filter(s => s.id !== req.params.id));
  res.json({ ok: true });
});

